259:         .atMost(TIMEOUT_DATA_AVAILABILITY)
260:         .pollInterval(Duration.ofMillis(100))
261:         .ignoreExceptions() // Ignore exceptions and continue retrying
262:         .untilAsserted(
263:             () -> {
264:               final var itemsObj =
265:                   camundaClient
266:                       .newBatchOperationItemsSearchRequest()
267:                       .filter(f -> f.batchOperationId(Long.toString(batchOperationKey)))
268:                       .send()
269:                       .join();
270: 
271:               final var filteredItems =
272:                   itemsObj.items().stream().filter(i -> i.getStatus() == state).toList();
273:               assertThat(filteredItems).hasSize(failedItemKeys.size());
274:               assertThat(filteredItems.stream().map(BatchOperationItem::getItemKey))
275:                   .hasSize(failedItemKeys.size());
276:             });
277:   }
