282:       final Map<String, Long> userTaskCounts) {
283:     flowNodeInstanceExistAndMatches(
284:         client,
285:         f ->
286:             f.processInstanceKey(processInstanceKey)
287:                 .state(ElementInstanceState.ACTIVE)
288:                 .type(ElementInstanceType.USER_TASK),
289:         f -> {
290:           final var elementIdCounts =
291:               f.stream()
292:                   .collect(
293:                       Collectors.groupingBy(ElementInstance::getElementId, Collectors.counting()));
294:           assertThat(elementIdCounts).containsAllEntriesOf(userTaskCounts);
295:         });
296:   }
