301:       final Consumer<List<ElementInstance>> asserter) {
302:     await()
303:         .atMost(TIMEOUT_DATA_AVAILABILITY)
304:         .untilAsserted(
305:             () -> {
306:               final var result =
307:                   client.newElementInstanceSearchRequest().filter(filter).send().join().items();
308:               asserter.accept(result);
309:             });
310:   }
