29: import io.camunda.zeebe.protocol.record.value.EntityType;
30: import io.camunda.zeebe.protocol.record.value.PermissionType;
31: import io.camunda.zeebe.stream.api.records.TypedRecord;
32: import io.camunda.zeebe.stream.api.state.KeyGenerator;
33: 
34: public class RoleAddEntityProcessor implements DistributedTypedRecordProcessor<RoleRecord> {
35: 
36:   public static final String ROLE_NOT_FOUND_ERROR_MESSAGE =
37:       "Expected to update role with ID '%s', but a role with this ID does not exist.";
38:   public static final String ENTITY_NOT_FOUND_ERROR_MESSAGE =
39:       "Expected to add an entity with ID '%s' and type '%s' to role with ID '%s', but the entity doesn't exist.";
40:   private static final String ENTITY_ALREADY_ASSIGNED_ERROR_MESSAGE =
41:       "Expected to add entity with ID '%s' to role with ID '%s', but the entity is already assigned to this role.";
42:   private final RoleState roleState;
43:   private final MappingState mappingState;
44:   private final MembershipState membershipState;
45:   private final GroupState groupState;
46:   private final AuthorizationCheckBehavior authCheckBehavior;
47:   private final KeyGenerator keyGenerator;
48:   private final StateWriter stateWriter;
49:   private final TypedRejectionWriter rejectionWriter;
50:   private final TypedResponseWriter responseWriter;
51:   private final CommandDistributionBehavior commandDistributionBehavior;
52: 
53:   public RoleAddEntityProcessor(
54:       final ProcessingState processingState,
55:       final AuthorizationCheckBehavior authCheckBehavior,
56:       final KeyGenerator keyGenerator,
57:       final Writers writers,
58:       final CommandDistributionBehavior commandDistributionBehavior) {
59:     roleState = processingState.getRoleState();
60:     mappingState = processingState.getMappingState();
61:     membershipState = processingState.getMembershipState();
62:     groupState = processingState.getGroupState();
63:     this.authCheckBehavior = authCheckBehavior;
64:     this.keyGenerator = keyGenerator;
65:     stateWriter = writers.state();
66:     rejectionWriter = writers.rejection();
67:     responseWriter = writers.response();
68:     this.commandDistributionBehavior = commandDistributionBehavior;
69:   }
70: 
71:   @Override
72:   public void processNewCommand(final TypedRecord<RoleRecord> command) {
73:     final var record = command.getValue();
74:     final var authorizationRequest =
75:         new AuthorizationRequest(command, AuthorizationResourceType.ROLE, PermissionType.UPDATE)
76:             .addResourceId(record.getRoleId());
77: 
78:     final var isAuthorized = authCheckBehavior.isAuthorized(authorizationRequest);
79:     if (isAuthorized.isLeft()) {
80:       final var rejection = isAuthorized.getLeft();
81:       rejectionWriter.appendRejection(command, rejection.type(), rejection.reason());
82:       responseWriter.writeRejectionOnCommand(command, rejection.type(), rejection.reason());
83:       return;
84:     }
85: 
86:     final var persistedRecord = roleState.getRole(record.getRoleId());
87:     if (persistedRecord.isEmpty()) {
88:       final var errorMessage = ROLE_NOT_FOUND_ERROR_MESSAGE.formatted(record.getRoleId());
89:       rejectionWriter.appendRejection(command, RejectionType.NOT_FOUND, errorMessage);
90:       responseWriter.writeRejectionOnCommand(command, RejectionType.NOT_FOUND, errorMessage);
91:       return;
92:     }
93: 
94:     final var entityId = record.getEntityId();
95:     final var entityType = record.getEntityType();
96:     if (!isEntityPresent(entityId, entityType, isInternalGroupsEnabled(command))) {
97:       final var errorMessage =
98:           ENTITY_NOT_FOUND_ERROR_MESSAGE.formatted(entityId, entityType, record.getRoleId());
99:       rejectionWriter.appendRejection(command, RejectionType.NOT_FOUND, errorMessage);
100:       responseWriter.writeRejectionOnCommand(command, RejectionType.NOT_FOUND, errorMessage);
101:       return;
102:     }
103: 
104:     if (isEntityAssigned(record)) {
105:       final var errorMessage =
106:           ENTITY_ALREADY_ASSIGNED_ERROR_MESSAGE.formatted(record.getEntityId(), record.getRoleId());
107:       rejectionWriter.appendRejection(command, RejectionType.ALREADY_EXISTS, errorMessage);
108:       responseWriter.writeRejectionOnCommand(command, RejectionType.ALREADY_EXISTS, errorMessage);
109:       return;
110:     }
111: 
112:     stateWriter.appendFollowUpEvent(record.getRoleKey(), RoleIntent.ENTITY_ADDED, record);
113:     responseWriter.writeEventOnCommand(
114:         record.getRoleKey(), RoleIntent.ENTITY_ADDED, record, command);
115: 
116:     final long distributionKey = keyGenerator.nextKey();
117:     commandDistributionBehavior
118:         .withKey(distributionKey)
119:         .inQueue(DistributionQueue.IDENTITY.getQueueId())
120:         .distribute(command);
121:   }
122: 
123:   @Override
124:   public void processDistributedCommand(final TypedRecord<RoleRecord> command) {
125:     final var record = command.getValue();
126:     if (isEntityAssigned(record)) {
127:       final var errorMessage =
128:           ENTITY_ALREADY_ASSIGNED_ERROR_MESSAGE.formatted(record.getEntityId(), record.getRoleId());
129:       rejectionWriter.appendRejection(command, RejectionType.ALREADY_EXISTS, errorMessage);
130:     } else {
131:       stateWriter.appendFollowUpEvent(command.getKey(), RoleIntent.ENTITY_ADDED, record);
132:     }
133: 
134:     commandDistributionBehavior.acknowledgeCommand(command);
135:   }
136: 
137:   private boolean isEntityPresent(
138:       final String entityId, final EntityType entityType, final boolean groupsClaimEnabled) {
139:     return switch (entityType) {
140:       case USER, CLIENT -> true; // With simple mappings, any username and client id can be assigned
141:       case MAPPING -> mappingState.get(entityId).isPresent();
142:       case GROUP -> !groupsClaimEnabled || groupState.get(entityId).isPresent();
143:       default -> false;
144:     };
145:   }
146: 
147:   private boolean isInternalGroupsEnabled(final TypedRecord<RoleRecord> command) {
148:     return Boolean.getBoolean(
149:         (String) command.getAuthorizations().get(Authorization.INTERNAL_GROUPS_ENABLED));
150:   }
151: 
152:   private boolean isEntityAssigned(final RoleRecord record) {
153:     return membershipState.hasRelation(
154:         record.getEntityType(), record.getEntityId(), RelationType.ROLE, record.getRoleId());
155:   }
156: }
157:
